     * by making the `nonReentrant` function external, and making it call a
     * `private` function that does the actual work.
     */
    modifier nonReentrant() {
        _nonReentrantBefore();
        _;
        _nonReentrantAfter();
    }

    function _nonReentrantBefore() private {
        // On the first call to nonReentrant, _status will be NOT_ENTERED
        if (_status == ENTERED) {
            revert ReentrancyGuardReentrantCall();
        }

        // Any calls to nonReentrant after this point will fail
        _status = ENTERED;
    }

    function _nonReentrantAfter() private {
        // By storing the original value once again, a refund is triggered (see
        // https://eips.ethereum.org/EIPS/eip-2200)
        _status = NOT_ENTERED;
    }

    /**
     * @dev Returns true if the reentrancy guard is currently set to "entered", which indicates there is a
     * `nonReentrant` function in the call stack.
     */
    function _reentrancyGuardEntered() internal view returns (bool) {
        return _status == ENTERED;
    }
}

contracts/SoulLiquidityManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title SoulLiquidityManager
 * @notice Manages liquidity pool creation, locking, and LP token staking
 * @dev Supports Uniswap V2/V3, PancakeSwap, and other DEX protocols
 */
contract SoulLiquidityManager is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ============ Structs ============

    struct LiquidityPool {
        address poolAddress;            // DEX pool address
        address token0;                 // First token (usually SOUL)
        address token1;                 // Second token (usually ETH/USDC)
        uint256 token0Amount;          // Amount of token0 added
        uint256 token1Amount;          // Amount of token1 added
        uint256 lpTokens;              // LP tokens received
        uint256 lockUntil;              // Lock expiration timestamp
        bool locked;                   // Whether pool is locked
        string dexName;                // DEX name (Uniswap, PancakeSwap, etc.)
    }

    struct LPStake {
        address staker;                 // Staker address
        uint256 lpTokenAmount;          // Amount of LP tokens staked
        uint256 stakedAt;               // Staking timestamp
        uint256 rewardsEarned;          // Total rewards earned
        uint256 lastRewardClaim;        // Last reward claim timestamp
    }

    // ============ State Variables ============

    /// @notice SOUL token
    IERC20 public immutable soulToken;

    /// @notice LP token interface (Uniswap V2 style)
    IERC20 public lpToken;

    /// @notice Total liquidity pools created
    uint256 public poolCount;

    /// @notice Mapping of pool ID to liquidity pool
    mapping(uint256 => LiquidityPool) public liquidityPools;

    /// @notice Mapping of staker to LP stake info
    mapping(address => LPStake) public lpStakes;

    /// @notice Total LP tokens staked
    uint256 public totalLPStaked;

    /// @notice Staking rewards pool
    uint256 public stakingRewardsPool;

    /// @notice Annual staking reward rate (basis points)
    uint256 public stakingRewardRateBps;

    /// @notice Minimum lock duration (in seconds)
    uint256 public minLockDuration;

    // ============ Events ============

    event LiquidityPoolCreated(
        uint256 indexed poolId,
        address indexed poolAddress,
        address token0,
        address token1,
        uint256 amount0,
        uint256 amount1,
        uint256 lpTokens,
        string dexName
    );

    event LiquidityLocked(
        uint256 indexed poolId,
        uint256 lockUntil
    );

    event LiquidityUnlocked(
        uint256 indexed poolId
    );

    event LPStaked(
        address indexed staker,
        uint256 amount
    );

    event LPUnstaked(
        address indexed staker,
        uint256 amount
    );

    event RewardsClaimed(
        address indexed staker,
        uint256 amount
    );

    event RewardsPoolFunded(
        uint256 amount
    );

    // ============ Constructor ============

    constructor(address _soulToken, address _owner) Ownable(_owner) {
        require(_soulToken != address(0), "Invalid token address");
        soulToken = IERC20(_soulToken);
        stakingRewardRateBps = 1000; // 10% default APY
        minLockDuration = 30 days;
    }

    // ============ Public Functions ============

    /**
     * @notice Stake LP tokens to earn rewards
     * @param _lpTokenAmount Amount of LP tokens to stake
     */
    function stakeLP(uint256 _lpTokenAmount) external nonReentrant {
        require(_lpTokenAmount > 0, "Invalid amount");
        require(lpToken.balanceOf(msg.sender) >= _lpTokenAmount, "Insufficient LP tokens");

        // Claim existing rewards first
        if (lpStakes[msg.sender].lpTokenAmount > 0) {
            _claimRewards(msg.sender);
        }

        // Transfer LP tokens
        lpToken.safeTransferFrom(msg.sender, address(this), _lpTokenAmount);

        // Update stake info
        LPStake storage stake = lpStakes[msg.sender];
        stake.staker = msg.sender;
        stake.lpTokenAmount += _lpTokenAmount;
        stake.stakedAt = block.timestamp;
        stake.lastRewardClaim = block.timestamp;

        totalLPStaked += _lpTokenAmount;

        emit LPStaked(msg.sender, _lpTokenAmount);
    }

    /**
     * @notice Unstake LP tokens
     * @param _lpTokenAmount Amount to unstake
     */
    function unstakeLP(uint256 _lpTokenAmount) external nonReentrant {
        LPStake storage stake = lpStakes[msg.sender];
        require(stake.lpTokenAmount >= _lpTokenAmount, "Insufficient staked");

        // Claim rewards
        _claimRewards(msg.sender);

        // Update stake
        stake.lpTokenAmount -= _lpTokenAmount;
        totalLPStaked -= _lpTokenAmount;

        // Transfer LP tokens back
        lpToken.safeTransfer(msg.sender, _lpTokenAmount);

        emit LPUnstaked(msg.sender, _lpTokenAmount);
    }

    /**
     * @notice Claim staking rewards
     */
    function claimRewards() external nonReentrant {
        _claimRewards(msg.sender);
    }

    // ============ Admin Functions ============

    /**
     * @notice Record liquidity pool creation (called after DEX interaction)
     * @param _poolAddress DEX pool address
     * @param _token0 First token address
     * @param _token1 Second token address
     * @param _amount0 Amount of token0
     * @param _amount1 Amount of token1
     * @param _lpTokens LP tokens received
     * @param _dexName DEX name
     */
    function recordLiquidityPool(
        address _poolAddress,
        address _token0,
        address _token1,
        uint256 _amount0,
        uint256 _amount1,
        uint256 _lpTokens,
        string memory _dexName
    ) external onlyOwner returns (uint256) {
        uint256 poolId = poolCount;
        liquidityPools[poolId] = LiquidityPool({
            poolAddress: _poolAddress,
            token0: _token0,
            token1: _token1,
            token0Amount: _amount0,
            token1Amount: _amount1,
            lpTokens: _lpTokens,
            lockUntil: 0,
            locked: false,
            dexName: _dexName
        });

        poolCount++;

        emit LiquidityPoolCreated(
            poolId,
            _poolAddress,
            _token0,
            _token1,
            _amount0,
            _amount1,
            _lpTokens,
            _dexName
        );

        return poolId;
    }

    /**
     * @notice Lock liquidity pool
     * @param _poolId Pool ID
     * @param _lockDuration Lock duration in seconds
     */
    function lockLiquidity(uint256 _poolId, uint256 _lockDuration) external onlyOwner {
        require(_poolId < poolCount, "Invalid pool ID");
        require(_lockDuration >= minLockDuration, "Lock duration too short");

        LiquidityPool storage pool = liquidityPools[_poolId];
        require(!pool.locked, "Already locked");

        pool.locked = true;
        pool.lockUntil = block.timestamp + _lockDuration;

        emit LiquidityLocked(_poolId, pool.lockUntil);
    }

    /**
     * @notice Unlock liquidity pool (after lock expires)
     * @param _poolId Pool ID
     */
    function unlockLiquidity(uint256 _poolId) external onlyOwner {
        require(_poolId < poolCount, "Invalid pool ID");

        LiquidityPool storage pool = liquidityPools[_poolId];
        require(pool.locked, "Not locked");
        require(block.timestamp >= pool.lockUntil, "Lock not expired");

        pool.locked = false;

        emit LiquidityUnlocked(_poolId);
    }

    /**
     * @notice Set LP token address
     */
    function setLPToken(address _lpToken) external onlyOwner {
        require(_lpToken != address(0), "Invalid address");
        lpToken = IERC20(_lpToken);
    }

    /**
     * @notice Fund staking rewards pool
     * @param _amount Amount of SOUL tokens to add
     */
    function fundRewardsPool(uint256 _amount) external onlyOwner {
        require(_amount > 0, "Invalid amount");
        require(soulToken.balanceOf(msg.sender) >= _amount, "Insufficient balance");

        soulToken.safeTransferFrom(msg.sender, address(this), _amount);
        stakingRewardsPool += _amount;

        emit RewardsPoolFunded(_amount);
    }

    /**
     * @notice Set staking reward rate
     * @param _rateBps New rate in basis points
     */
    function setStakingRewardRate(uint256 _rateBps) external onlyOwner {
        require(_rateBps <= 5000, "Rate too high"); // Max 50%
        stakingRewardRateBps = _rateBps;
    }

    /**
     * @notice Set minimum lock duration
     */
    function setMinLockDuration(uint256 _duration) external onlyOwner {
        minLockDuration = _duration;
    }

    // ============ Internal Functions ============

    function _claimRewards(address _staker) internal {
        LPStake storage stake = lpStakes[_staker];
        if (stake.lpTokenAmount == 0) return;

        uint256 rewards = calculateRewards(_staker);
        if (rewards > 0 && rewards <= stakingRewardsPool) {
            stakingRewardsPool -= rewards;
            stake.rewardsEarned += rewards;
            stake.lastRewardClaim = block.timestamp;

            soulToken.safeTransfer(_staker, rewards);

            emit RewardsClaimed(_staker, rewards);
        }
    }

    // ============ View Functions ============

    /**
     * @notice Calculate pending rewards for staker
     */
    function calculateRewards(address _staker) public view returns (uint256) {
        LPStake storage stake = lpStakes[_staker];
        if (stake.lpTokenAmount == 0 || totalLPStaked == 0) return 0;

        uint256 duration = block.timestamp - stake.lastRewardClaim;
        uint256 annualReward = (stake.lpTokenAmount * stakingRewardRateBps) / 10000;
        return (annualReward * duration) / (365 days);
    }

    /**
     * @notice Get staker info
     */
    function getStakerInfo(address _staker) external view returns (
        uint256 stakedAmount,
        uint256 pendingRewards,
        uint256 totalEarned,
        uint256 stakedAt
    ) {
        LPStake storage stake = lpStakes[_staker];
        return (
            stake.lpTokenAmount,
            calculateRewards(_staker),
            stake.rewardsEarned,
            stake.stakedAt
        );
    }

    /**
     * @notice Check if pool is locked
     */
    function isPoolLocked(uint256 _poolId) external view returns (bool) {
        if (_poolId >= poolCount) return false;
        LiquidityPool storage pool = liquidityPools[_poolId];
        return pool.locked && block.timestamp < pool.lockUntil;
    }
}

contracts/SoulTokenSale.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/Address.sol";

/**
 * @title SoulTokenSale
 * @notice Public token sale contract for SOUL token fundraising
 * @dev Supports multiple sale phases, whitelist, and automatic refunds
 */
contract SoulTokenSale is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;
    using Address for address payable;

    // ============ Constants ============

    /// @notice Sale phases
    enum SalePhase {
        NotStarted,
        PrivateSale,
        PublicSale,
        Ended,
        Refunded
    }

    // ============ State Variables ============

    /// @notice SOUL token being sold
    IERC20 public immutable soulToken;

    /// @notice Payment token (ETH or stablecoin)
    address public paymentToken; // address(0) for ETH

    /// @notice Current sale phase
    SalePhase public currentPhase;

    /// @notice Sale start time
    uint256 public saleStartTime;

    /// @notice Sale end time
    uint256 public saleEndTime;

    /// @notice Soft cap (minimum to raise)
    uint256 public softCap;

    /// @notice Hard cap (maximum to raise)
    uint256 public hardCap;

    /// @notice Total raised
    uint256 public totalRaised;

    /// @notice Total tokens sold
    uint256 public totalTokensSold;

    /// @notice Price per token (in payment token, with decimals)
    uint256 public tokenPrice;

    /// @notice Minimum purchase amount
    uint256 public minPurchase;

    /// @notice Maximum purchase amount per wallet
    uint256 public maxPurchase;

    /// @notice Whitelist enabled
    bool public whitelistEnabled;

    /// @notice Refund enabled (if soft cap not met)
    bool public refundEnabled;

    // ============ Mappings ============

    /// @notice Amount contributed by each address
    mapping(address => uint256) public contributions;

    /// @notice Tokens purchased by each address
    mapping(address => uint256) public tokensPurchased;

    /// @notice Whitelist status
    mapping(address => bool) public whitelist;

    /// @notice Refund claimed status
    mapping(address => bool) public refundClaimed;

    // ============ Events ============

    event SalePhaseChanged(SalePhase oldPhase, SalePhase newPhase);
    event TokensPurchased(address indexed buyer, uint256 amount, uint256 tokens);
    event WhitelistUpdated(address indexed user, bool status);
    event RefundClaimed(address indexed user, uint256 amount);
    event FundsWithdrawn(address indexed recipient, uint256 amount);
    event SaleEnded(uint256 totalRaised, uint256 totalTokensSold);

    // ============ Modifiers ============

    modifier onlyActiveSale() {
        require(
            currentPhase == SalePhase.PrivateSale || currentPhase == SalePhase.PublicSale,
            "Sale not active"
        );
        require(block.timestamp >= saleStartTime && block.timestamp <= saleEndTime, "Sale not in progress");
        _;
    }

    modifier onlyWhitelisted() {
        if (whitelistEnabled) {
            require(whitelist[msg.sender], "Not whitelisted");
        }
        _;
    }

    // ============ Constructor ============

    constructor(
        address _soulToken,
        address _paymentToken,
        uint256 _softCap,
        uint256 _hardCap,
        uint256 _tokenPrice,
        uint256 _minPurchase,
        uint256 _maxPurchase,
        address _owner
    ) Ownable(_owner) {
        require(_soulToken != address(0), "Invalid token address");
        require(_softCap > 0 && _hardCap > _softCap, "Invalid caps");
        require(_tokenPrice > 0, "Invalid price");
        require(_owner != address(0), "Invalid owner");

        soulToken = IERC20(_soulToken);
        paymentToken = _paymentToken;
        softCap = _softCap;
        hardCap = _hardCap;
        tokenPrice = _tokenPrice;
        minPurchase = _minPurchase;
        maxPurchase = _maxPurchase;
        currentPhase = SalePhase.NotStarted;
    }

    // ============ Public Functions ============

    /**
     * @notice Purchase SOUL tokens
     * @param _amount Amount of payment token to spend
     */
    function buyTokens(uint256 _amount) external payable nonReentrant onlyActiveSale onlyWhitelisted {
        require(_amount >= minPurchase, "Amount below minimum");
        require(totalRaised + _amount <= hardCap, "Hard cap reached");

        uint256 paymentAmount = paymentToken == address(0) ? msg.value : _amount;
        require(paymentAmount > 0, "Invalid amount");

        uint256 userContribution = contributions[msg.sender] + paymentAmount;
        require(userContribution <= maxPurchase, "Exceeds max purchase");

        // Calculate tokens to receive
        uint256 tokensToReceive = (paymentAmount * 10**18) / tokenPrice;
        require(tokensToReceive > 0, "Insufficient amount for tokens");

        // Check contract has enough tokens
        require(soulToken.balanceOf(address(this)) >= totalTokensSold + tokensToReceive, "Insufficient tokens");

        // Transfer payment
        if (paymentToken == address(0)) {
            require(msg.value == paymentAmount, "ETH amount mismatch");
        } else {
            IERC20(paymentToken).safeTransferFrom(msg.sender, address(this), paymentAmount);
        }

        // Update state
        contributions[msg.sender] += paymentAmount;
        tokensPurchased[msg.sender] += tokensToReceive;
        totalRaised += paymentAmount;
        totalTokensSold += tokensToReceive;

        // Transfer tokens to buyer
        soulToken.safeTransfer(msg.sender, tokensToReceive);

        emit TokensPurchased(msg.sender, paymentAmount, tokensToReceive);

        // Check if hard cap reached
        if (totalRaised >= hardCap) {
            _endSale();
        }
    }

    /**
     * @notice Claim refund if soft cap not met
     */
    function claimRefund() external nonReentrant {
        require(refundEnabled, "Refunds not enabled");
        require(contributions[msg.sender] > 0, "No contribution");
        require(!refundClaimed[msg.sender], "Refund already claimed");

        uint256 refundAmount = contributions[msg.sender];
        refundClaimed[msg.sender] = true;

        if (paymentToken == address(0)) {
            payable(msg.sender).sendValue(refundAmount);
        } else {
            IERC20(paymentToken).safeTransfer(msg.sender, refundAmount);
        }

        emit RefundClaimed(msg.sender, refundAmount);
    }

    // ============ Admin Functions ============

    /**
     * @notice Start the sale
     * @param _phase Sale phase to start
     * @param _duration Sale duration in seconds
     */
    function startSale(SalePhase _phase, uint256 _duration) external onlyOwner {
        require(currentPhase == SalePhase.NotStarted, "Sale already started");
        require(_phase == SalePhase.PrivateSale || _phase == SalePhase.PublicSale, "Invalid phase");

        saleStartTime = block.timestamp;
        saleEndTime = block.timestamp + _duration;
        currentPhase = _phase;

        emit SalePhaseChanged(SalePhase.NotStarted, _phase);
    }

    /**
     * @notice Change sale phase
     */
    function changePhase(SalePhase _newPhase) external onlyOwner {
        SalePhase oldPhase = currentPhase;
        currentPhase = _newPhase;
        emit SalePhaseChanged(oldPhase, _newPhase);
    }

    /**
     * @notice End the sale
     */
    function endSale() external onlyOwner {
        _endSale();
    }

    /**
     * @notice Enable refunds (if soft cap not met)
     */
    function enableRefunds() external onlyOwner {
        require(currentPhase == SalePhase.Ended, "Sale not ended");
        require(totalRaised < softCap, "Soft cap met");
        refundEnabled = true;
    }

    /**
     * @notice Withdraw raised funds (only if soft cap met)
     */
    function withdrawFunds() external onlyOwner {
        require(currentPhase == SalePhase.Ended, "Sale not ended");
        require(totalRaised >= softCap, "Soft cap not met");
        require(!refundEnabled, "Refunds enabled");

        uint256 amount = paymentToken == address(0) 
            ? address(this).balance 
            : IERC20(paymentToken).balanceOf(address(this));

        if (paymentToken == address(0)) {
            payable(owner()).sendValue(amount);
        } else {
            IERC20(paymentToken).safeTransfer(owner(), amount);
        }

        emit FundsWithdrawn(owner(), amount);
    }

    /**
     * @notice Add/remove whitelist addresses
     */
    function updateWhitelist(address[] calldata _addresses, bool _status) external onlyOwner {
        for (uint256 i = 0; i < _addresses.length; i++) {
            whitelist[_addresses[i]] = _status;
            emit WhitelistUpdated(_addresses[i], _status);
        }
    }

    /**
     * @notice Toggle whitelist requirement
     */
    function setWhitelistEnabled(bool _enabled) external onlyOwner {
        whitelistEnabled = _enabled;
    }

    /**
     * @notice Withdraw unsold tokens
     */
    function withdrawUnsoldTokens() external onlyOwner {
        require(currentPhase == SalePhase.Ended, "Sale not ended");
        uint256 unsold = soulToken.balanceOf(address(this));
        soulToken.safeTransfer(owner(), unsold);
    }

    // ============ Internal Functions ============

    function _endSale() internal {
        currentPhase = SalePhase.Ended;
        emit SaleEnded(totalRaised, totalTokensSold);

        if (totalRaised < softCap) {
            refundEnabled = true;
        }
    }

    // ============ View Functions ============

    /**
     * @notice Get sale progress percentage
     */
    function getSaleProgress() external view returns (uint256) {
        if (hardCap == 0) return 0;
        return (totalRaised * 100) / hardCap;
    }

    /**
     * @notice Check if address can purchase
     */
    function canPurchase(address _user) external view returns (bool) {
        if (whitelistEnabled && !whitelist[_user]) return false;
        if (currentPhase != SalePhase.PrivateSale && currentPhase != SalePhase.PublicSale) return false;
        if (block.timestamp < saleStartTime || block.timestamp > saleEndTime) return false;
        if (totalRaised >= hardCap) return false;
        return true;
    }

    /**
     * @notice Get tokens for amount
     */
    function getTokensForAmount(uint256 _amount) external view returns (uint256) {
        return (_amount * 10**18) / tokenPrice;
    }
}

contracts/SoulVesting.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title SoulVesting
 * @notice Flexible vesting contract for SOUL token investors and team
 * @dev Supports multiple vesting schedules, cliff periods, and early unlock penalties
 */
contract SoulVesting is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ============ Structs ============

    struct VestingSchedule {
        address beneficiary;           // Address that will receive tokens
        uint256 totalAmount;            // Total amount to be vested
        uint256 released;               // Amount already released
        uint256 startTime;               // Vesting start time (cliff)
        uint256 duration;               // Vesting duration in seconds
        uint256 cliffDuration;           // Cliff duration in seconds
        bool revocable;                 // Whether vesting can be revoked
        bool revoked;                   // Whether vesting has been revoked
        uint256 earlyUnlockPenalty;     // Penalty percentage for early unlock (basis points)
    }

    // ============ State Variables ============

    /// @notice SOUL token being vested
    IERC20 public immutable soulToken;

    /// @notice Total vesting schedules
    uint256 public vestingScheduleCount;

    /// @notice Mapping of schedule ID to vesting schedule
    mapping(uint256 => VestingSchedule) public vestingSchedules;

    /// @notice Mapping of beneficiary to schedule IDs
    mapping(address => uint256[]) public beneficiarySchedules;

    /// @notice Total amount in vesting
    uint256 public totalVestingAmount;

    /// @notice Total amount released
    uint256 public totalReleased;

    // ============ Events ============

    event VestingScheduleCreated(
        uint256 indexed scheduleId,
        address indexed beneficiary,
        uint256 totalAmount,
        uint256 startTime,
        uint256 duration,
        uint256 cliffDuration
    );

    event TokensReleased(
        uint256 indexed scheduleId,
        address indexed beneficiary,
        uint256 amount
    );

    event VestingRevoked(
        uint256 indexed scheduleId,
        address indexed beneficiary,
        uint256 revokedAmount
    );

    event EarlyUnlock(
        uint256 indexed scheduleId,
        address indexed beneficiary,
        uint256 amount,
        uint256 penalty
    );

    // ============ Modifiers ============

    modifier onlyValidSchedule(uint256 _scheduleId) {
        require(_scheduleId < vestingScheduleCount, "Invalid schedule ID");
        require(!vestingSchedules[_scheduleId].revoked, "Schedule revoked");
        _;
    }

    // ============ Constructor ============

    constructor(address _soulToken, address _owner) Ownable(_owner) {
        require(_soulToken != address(0), "Invalid token address");
        soulToken = IERC20(_soulToken);
    }

    // ============ Public Functions ============

    /**
     * @notice Release vested tokens for a schedule
     * @param _scheduleId Vesting schedule ID
     */
    function release(uint256 _scheduleId) external nonReentrant onlyValidSchedule(_scheduleId) {
        VestingSchedule storage schedule = vestingSchedules[_scheduleId];
        require(schedule.beneficiary == msg.sender || msg.sender == owner(), "Not authorized");

        uint256 releasable = getReleasableAmount(_scheduleId);
        require(releasable > 0, "No tokens to release");

        schedule.released += releasable;
        totalReleased += releasable;

        soulToken.safeTransfer(schedule.beneficiary, releasable);

        emit TokensReleased(_scheduleId, schedule.beneficiary, releasable);
    }

    /**
     * @notice Early unlock with penalty
     * @param _scheduleId Vesting schedule ID
     * @param _amount Amount to unlock early
     */
    function earlyUnlock(uint256 _scheduleId, uint256 _amount) external nonReentrant onlyValidSchedule(_scheduleId) {
        VestingSchedule storage schedule = vestingSchedules[_scheduleId];
        require(schedule.beneficiary == msg.sender, "Not beneficiary");
        require(_amount > 0, "Invalid amount");

        uint256 vested = getVestedAmount(_scheduleId);
        uint256 available = vested - schedule.released;
        require(_amount <= available, "Amount exceeds available");

        // Calculate penalty
        uint256 penalty = (_amount * schedule.earlyUnlockPenalty) / 10000;
        uint256 netAmount = _amount - penalty;

        schedule.released += _amount;
        totalReleased += _amount;

        // Transfer net amount to beneficiary
        soulToken.safeTransfer(schedule.beneficiary, netAmount);

        // Burn or send penalty to treasury (owner)
        if (penalty > 0) {
            soulToken.safeTransfer(owner(), penalty);
        }

        emit EarlyUnlock(_scheduleId, schedule.beneficiary, netAmount, penalty);
    }

    // ============ Admin Functions ============

    /**
     * @notice Create a new vesting schedule
     * @param _beneficiary Address that will receive tokens
     * @param _totalAmount Total amount to vest
     * @param _startTime Vesting start time (0 = now)
     * @param _duration Vesting duration in seconds
     * @param _cliffDuration Cliff duration in seconds
     * @param _revocable Whether vesting can be revoked
     * @param _earlyUnlockPenalty Penalty for early unlock (basis points)
     */
    function createVestingSchedule(
        address _beneficiary,
        uint256 _totalAmount,
        uint256 _startTime,
        uint256 _duration,
        uint256 _cliffDuration,
        bool _revocable,
        uint256 _earlyUnlockPenalty
    ) external onlyOwner returns (uint256) {
        require(_beneficiary != address(0), "Invalid beneficiary");
        require(_totalAmount > 0, "Invalid amount");
        require(_duration > 0, "Invalid duration");
        require(_cliffDuration <= _duration, "Cliff exceeds duration");
        require(_earlyUnlockPenalty <= 5000, "Penalty too high"); // Max 50%

        uint256 startTime = _startTime == 0 ? block.timestamp : _startTime;

        // Check contract has enough tokens
        require(
            soulToken.balanceOf(address(this)) >= totalVestingAmount + _totalAmount,
            "Insufficient tokens in contract"
        );

        uint256 scheduleId = vestingScheduleCount;
        vestingSchedules[scheduleId] = VestingSchedule({
            beneficiary: _beneficiary,
            totalAmount: _totalAmount,
            released: 0,
            startTime: startTime,
            duration: _duration,
            cliffDuration: _cliffDuration,
            revocable: _revocable,
            revoked: false,
            earlyUnlockPenalty: _earlyUnlockPenalty
        });

        beneficiarySchedules[_beneficiary].push(scheduleId);
        vestingScheduleCount++;
        totalVestingAmount += _totalAmount;

        emit VestingScheduleCreated(
            scheduleId,
            _beneficiary,
            _totalAmount,
            startTime,
            _duration,
            _cliffDuration
        );

        return scheduleId;
    }

    /**
     * @notice Revoke a vesting schedule (if revocable)
     * @param _scheduleId Vesting schedule ID
     */
    function revoke(uint256 _scheduleId) external onlyOwner onlyValidSchedule(_scheduleId) {
        VestingSchedule storage schedule = vestingSchedules[_scheduleId];
        require(schedule.revocable, "Not revocable");

        uint256 vested = getVestedAmount(_scheduleId);
        uint256 revokedAmount = schedule.totalAmount - vested;

        schedule.revoked = true;
        totalVestingAmount -= revokedAmount;

        // Transfer revoked tokens back to owner
        if (revokedAmount > 0) {
            soulToken.safeTransfer(owner(), revokedAmount);
        }

        emit VestingRevoked(_scheduleId, schedule.beneficiary, revokedAmount);
    }

    /**
     * @notice Batch create vesting schedules
     */
    function batchCreateVestingSchedules(
        address[] calldata _beneficiaries,
        uint256[] calldata _totalAmounts,
        uint256 _startTime,
        uint256 _duration,
        uint256 _cliffDuration,
        bool _revocable,
        uint256 _earlyUnlockPenalty
    ) external onlyOwner {
        require(_beneficiaries.length == _totalAmounts.length, "Array length mismatch");

        for (uint256 i = 0; i < _beneficiaries.length; i++) {
            this.createVestingSchedule(
                _beneficiaries[i],
                _totalAmounts[i],
                _startTime,
                _duration,
                _cliffDuration,
                _revocable,
                _earlyUnlockPenalty
            );
        }
    }

    // ============ View Functions ============

    /**
     * @notice Get vested amount for a schedule
     * @param _scheduleId Vesting schedule ID
     */
    function getVestedAmount(uint256 _scheduleId) public view returns (uint256) {
        VestingSchedule storage schedule = vestingSchedules[_scheduleId];

        if (block.timestamp < schedule.startTime + schedule.cliffDuration) {
            return 0; // Still in cliff period
        }

        if (block.timestamp >= schedule.startTime + schedule.duration) {
            return schedule.totalAmount; // Fully vested
        }

        // Linear vesting
        uint256 elapsed = block.timestamp - schedule.startTime;
        return (schedule.totalAmount * elapsed) / schedule.duration;
    }

    /**
     * @notice Get releasable amount for a schedule
     * @param _scheduleId Vesting schedule ID
     */
    function getReleasableAmount(uint256 _scheduleId) public view returns (uint256) {
        VestingSchedule storage schedule = vestingSchedules[_scheduleId];
        uint256 vested = getVestedAmount(_scheduleId);
        return vested - schedule.released;
    }

    /**
     * @notice Get all schedules for a beneficiary
     * @param _beneficiary Beneficiary address
     */
    function getBeneficiarySchedules(address _beneficiary) external view returns (uint256[] memory) {
        return beneficiarySchedules[_beneficiary];
    }

    /**
     * @notice Get schedule details
     * @param _scheduleId Vesting schedule ID
     */
    function getSchedule(uint256 _scheduleId) external view returns (VestingSchedule memory) {
        return vestingSchedules[_scheduleId];
    }

    /**
     * @notice Get total vested and releasable for beneficiary
     * @param _beneficiary Beneficiary address
     */
    function getBeneficiaryInfo(address _beneficiary) external view returns (
        uint256 totalVested,
        uint256 totalReleasable,
        uint256 beneficiaryTotalReleased
    ) {
        uint256[] memory schedules = beneficiarySchedules[_beneficiary];

        for (uint256 i = 0; i < schedules.length; i++) {
            if (!vestingSchedules[schedules[i]].revoked) {
                totalVested += getVestedAmount(schedules[i]);
                totalReleasable += getReleasableAmount(schedules[i]);
                beneficiaryTotalReleased += vestingSchedules[schedules[i]].released;
            }
        }
    }
}

